{"path": "units/chain/stage1.py", "content": "import csv


def parse_orders(path):
    """Parse a CSV with header id,qty,price into int-valued dict rows."""
    rows = []
    with open(path, newline="") as f:
        reader = csv.DictReader(f)
        for row in reader:
            rows.append({
                "id": int(row["id"]),
                "qty": int(row["qty"]),
                "price": int(row["price"]),
            })
    return rows
"}

{"path": "units/chain/stage3.py", "content": "def total_by_price(rows):
    """Sum qty grouped by price."""
    totals = {}
    for row in rows:
        totals[row["price"]] = totals.get(row["price"], 0) + row["qty"]
    return totals
"}

{"path": "units/chain/stage4.py", "content": "def report(totals):
    """Render "price:qty\\n" lines sorted ascending by price."""
    return "".join(f"{price}:{totals[price]}\n" for price in sorted(totals))
"}
